
  document.addEventListener('DOMContentLoaded', () => {
    gsap.registerPlugin(ScrollTrigger);

    const counters = document.querySelectorAll('[data-counter]');

    counters.forEach((el) => {
      // ambil angka termasuk decimal
      const raw = el.textContent.trim();
      const target = Number(raw.replace(/[^0-9.-]/g, ''));
      if (isNaN(target)) return;

      // cek jumlah angka di belakang koma
      const decimalPlaces = (raw.split('.')[1] || '').length;

      // dataset config
      const duration = parseFloat(el.dataset.duration) || 1.5;
      const delay = parseFloat(el.dataset.delay) || 0;
      const ease = el.dataset.ease || 'power1.out';
      const start = el.dataset.start || 'top 80%';
      const once = el.dataset.once !== 'false';

      gsap.fromTo(
        el,
        { innerText: 0 },
        {
          innerText: target,
          duration: duration,
          delay: delay,
          ease: ease,
          snap: { innerText: 1 / Math.pow(10, decimalPlaces) }, // penting untuk decimal
          scrollTrigger: {
            trigger: el,
            start: start,
            once: once,
          },
          onUpdate() {
            const value = parseFloat(el.innerText);
            el.innerText = value.toFixed(decimalPlaces);
          },
        },
      );
    });
  });

